#!/usr/bin/env bash
# 0.48.0: weekly ops pull from D1 (vc-spot-receipts): top 20 normalized 404 paths and the paywall funnel, last 7 UTC days.
# 0.49.2: placeholder hosts (example.com/.org/.net + subdomains, localhost, 127.0.0.1, test.com, *.test, *.invalid,
# *.example) are filtered out of the funnel and endpoints-checked/demand; the raw counts and the placeholder hits are
# printed separately. PH_SQL is ops.js placeholderSql("url") verbatim (tests/placeholder_test.mjs checks it).
# Read-only. Needs a wrangler login (or CLOUDFLARE_API_TOKEN with D1 read). Usage: worker/scripts/ops_weekly.sh [days]
# Alternative without wrangler: curl -s -H "Authorization: Bearer $WATCH_STATS_TOKEN" "https://api.402xagent.com/v1/ops/stats?days=7"
set -euo pipefail
DAYS="${1:-7}"
case "$DAYS" in ''|*[!0-9]*) echo "days must be an integer" >&2; exit 2;; esac
cd "$(dirname "$0")/.."
SINCE="$(date -u -d "-$((DAYS - 1)) days" +%F)"
W=(npx -y -p node@22 -p wrangler@latest wrangler d1 execute vc-spot-receipts --remote --config wrangler.toml)
echo "== top 20 404 paths since $SINCE (UTC)"
"${W[@]}" --command "SELECT method, path, SUM(n) AS n FROM notfound_daily WHERE day >= '$SINCE' GROUP BY method, path ORDER BY n DESC, path LIMIT 20"
echo "== paywall funnel since $SINCE (UTC), placeholder hosts excluded"
"${W[@]}" --command "SELECT route, segment, event, reason, SUM(n) AS n FROM paywall_daily WHERE day >= '$SINCE' AND event != 'placeholder' GROUP BY route, segment, event, reason ORDER BY route, segment, event, reason"
echo "== placeholder hits since $SINCE (UTC) (raw = funnel above + these)"
"${W[@]}" --command "SELECT route, segment, reason AS paid_or_unpaid, SUM(n) AS n FROM paywall_daily WHERE day >= '$SINCE' AND event = 'placeholder' GROUP BY route, segment, reason ORDER BY n DESC"
PH_SQL="(rtrim(lower(substr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1), 1, instr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1) || ':', ':') - 1)), '.') IN ('example.com', 'example.org', 'example.net', 'localhost', '127.0.0.1', 'test.com', 'test', 'invalid', 'example') OR rtrim(lower(substr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1), 1, instr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1) || ':', ':') - 1)), '.') LIKE '%.example.com' OR rtrim(lower(substr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1), 1, instr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1) || ':', ':') - 1)), '.') LIKE '%.example.org' OR rtrim(lower(substr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1), 1, instr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1) || ':', ':') - 1)), '.') LIKE '%.example.net' OR rtrim(lower(substr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1), 1, instr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1) || ':', ':') - 1)), '.') LIKE '%.localhost' OR rtrim(lower(substr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1), 1, instr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1) || ':', ':') - 1)), '.') LIKE '%.test' OR rtrim(lower(substr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1), 1, instr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1) || ':', ':') - 1)), '.') LIKE '%.invalid' OR rtrim(lower(substr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1), 1, instr(substr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), instr(substr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/'), 1, instr(replace(replace(substr(url, instr(url, '://') + 3), '?', '/'), '#', '/') || '/', '/') - 1), '@') + 1) || ':', ':') - 1)), '.') LIKE '%.example')"
echo "== endpoints checked + demand since $SINCE (UTC): true (no placeholder hosts) and raw"
"${W[@]}" --command "SELECT COUNT(DISTINCT CASE WHEN NOT $PH_SQL THEN url END) AS endpoints, COUNT(DISTINCT url) AS endpoints_raw, SUM(CASE WHEN NOT $PH_SQL THEN 1 ELSE 0 END) AS checks, COUNT(*) AS checks_raw, SUM(CASE WHEN check_type != 'self-checked' AND NOT $PH_SQL THEN 1 ELSE 0 END) AS demand, SUM(CASE WHEN check_type != 'self-checked' THEN 1 ELSE 0 END) AS demand_raw, SUM(CASE WHEN $PH_SQL THEN 1 ELSE 0 END) AS placeholder_checks FROM spot_receipts WHERE created_at >= '${SINCE}T00:00:00Z'"
# 0.78.0 settlement activity (migration 0035; empty until SETTLE_MATCH=1). Counts only, per endpoint. Caveat always printed.
echo "== settlement activity since $SINCE (UTC): Base USDC transfers to the quoted payTo after live checks"
echo "caveat: absence of an observed settlement never means the endpoint was not paid (other networks/assets, outside the window, other address, batched/off-chain, skipped blocks, RPC misses). We cannot link a payer to whoever requested a check: this is settlement activity per endpoint, not what callers did with our verdicts."
"${W[@]}" --command "SELECT verdict, COUNT(*) AS checks, SUM(exact_n > 0) AS with_exact_high, SUM(exact_n = 0 AND near_n > 0) AS near_only_low, SUM(exact_n) AS exact_transfers, SUM(near_n) AS near_transfers FROM settle_checks WHERE checked_at >= '${SINCE}T00:00:00Z' GROUP BY verdict ORDER BY verdict" || echo "(settle_checks missing: migration 0035 not applied)"
"${W[@]}" --command "SELECT method, url, COUNT(*) AS checks, SUM(exact_n > 0) AS with_exact_high, SUM(exact_n = 0 AND near_n > 0) AS near_only_low, SUM(exact_n) AS exact_transfers, SUM(near_n) AS near_transfers, GROUP_CONCAT(DISTINCT amount_atomic) AS quoted_atomic, GROUP_CONCAT(DISTINCT exact_first_bucket) AS first_exact_buckets FROM settle_checks WHERE checked_at >= '${SINCE}T00:00:00Z' GROUP BY method, url ORDER BY with_exact_high DESC, checks DESC LIMIT 25" || true
"${W[@]}" --command "SELECT SUM(runs) AS runs, SUM(blocks) AS blocks, SUM(gap_blocks) AS gap_blocks, SUM(log_queries) AS get_logs, SUM(rpc_calls) AS rpc_calls, SUM(rpc_errors) AS rpc_errors, SUM(other_n) AS other_transfers, SUM(self_excluded) AS self_excluded FROM settle_runs_daily WHERE day >= '$SINCE'" || true
